<script setup>import {ref,onMounted,onUnmounted} from 'vue';const online=ref(navigator.onLine);const on=()=>online.value=true,onf=()=>online.value=false;onMounted(()=>{addEventListener('online',on);addEventListener('offline',onf)});onUnmounted(()=>{removeEventListener('online',on);removeEventListener('offline',onf)})</script><template><div v-if="!online" class="pill warning">Offline — core demo screens remain available; sync when connected.</div></template>
